'use strict';

const PDFDocument = require('pdfkit');
const { normalizeForPdf } = require('./imageNormalizer');
const { DEFECT_LABELS } = require('../services/defectService');

const COLORS = {
  forest: '#1F5136',
  emerald: '#2F7D5B',
  mint: '#E8F3EC',
  charcoal: '#1F2937',
  muted: '#5B6B63',
  gold: '#A8843C',
  line: '#DCE7E0',
  danger: '#A33A3A',
};

const DISCLAIMER =
  'This report is generated by an automated computer-vision system. It is not a ' +
  'certified commercial grading result and does not replace laboratory testing or ' +
  'inspection by a qualified grader.';

function gradeColor(grade) {
  if (grade === 'Grade A') return COLORS.emerald;
  if (grade === 'Grade B') return COLORS.gold;
  if (grade === 'Grade C') return '#C77A2E';
  return COLORS.danger;
}

/**
 * Format per-grade counts, showing only grades the checkpoint actually
 * supports. Legacy scans (no supportedGrades) fall back to A/B.
 */
function gradeCountsText(scan) {
  if (scan.gradingEnabled === false) return 'Not available (grading disabled by policy)';
  const counts = scan.gradeCounts && typeof scan.gradeCounts === 'object'
    ? scan.gradeCounts
    : { A: scan.gradeA, B: scan.gradeB, C: scan.gradeC, D: scan.gradeD };
  const parts = Object.entries(counts)
    .filter(([, value]) => value !== null && value !== undefined)
    .map(([letter, value]) => `${letter}: ${safe(value, 0)}`);
  return `${safe(scan.totalCount, 0)}${parts.length ? ` (${parts.join(', ')})` : ''}`;
}

function gradeLabel(scan, grade) {
  if (scan.gradingEnabled === false) return 'Disabled by administrator';
  if (!grade) return 'Hidden by display policy';
  return safe(grade);
}

function safe(value, fallback = 'Not available') {
  if (value === null || value === undefined || value === '') return fallback;
  return String(value);
}

function formatDate(value) {
  const date = value ? new Date(value) : new Date();
  if (Number.isNaN(date.getTime())) return safe(value);
  return date.toLocaleString('en-GB', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function drawHeader(doc, subtitle) {
  doc.rect(0, 0, doc.page.width, 92).fill(COLORS.forest);
  doc
    .fillColor('#FFFFFF')
    .font('Helvetica-Bold')
    .fontSize(20)
    .text('Arecanut Quality Grading', 48, 28);
  doc
    .font('Helvetica')
    .fontSize(9)
    .fillColor('#CFE3D6')
    .text(subtitle, 48, 56);
  doc
    .fontSize(8)
    .fillColor('#CFE3D6')
    .text('ARECANUT QUALITY GRADING SYSTEM · Deep Learning Quality Assessment', 48, 70);
  doc.fillColor(COLORS.charcoal);
  doc.y = 118;
}

function sectionTitle(doc, title) {
  if (doc.y > doc.page.height - 130) doc.addPage();
  doc
    .font('Helvetica-Bold')
    .fontSize(11)
    .fillColor(COLORS.forest)
    .text(title.toUpperCase(), 48, doc.y, { characterSpacing: 0.8 });
  doc
    .moveTo(48, doc.y + 4)
    .lineTo(doc.page.width - 48, doc.y + 4)
    .strokeColor(COLORS.line)
    .lineWidth(1)
    .stroke();
  doc.moveDown(0.7);
}

function keyValue(doc, label, value, options = {}) {
  const left = options.left || 48;
  const width = options.width || 240;
  const labelWidth = options.labelWidth || 105;
  const y = doc.y;
  doc
    .font('Helvetica')
    .fontSize(8.5)
    .fillColor(COLORS.muted)
    .text(label, left, y, { width: labelWidth });
  doc
    .font('Helvetica-Bold')
    .fontSize(9)
    .fillColor(options.color || COLORS.charcoal)
    .text(safe(value), left + labelWidth, y, { width: width - labelWidth });
  doc.y = Math.max(doc.y, y + 14);
}

async function prepareImages(images = {}) {
  const result = {};
  const errors = [];
  for (const kind of ['original', 'processed', 'annotated']) {
    const buffer = images[kind];
    if (!buffer) {
      result[kind] = null;
      continue;
    }
    try {
      result[kind] = await normalizeForPdf(buffer, {
        maxDimension: kind === 'original' ? 1800 : 1600,
      });
    } catch (error) {
      result[kind] = null;
      errors.push({
        kind,
        message: String(error.message || error).slice(0, 240),
      });
    }
  }
  result.errors = errors;
  return result;
}

function addImage(doc, image, caption, width = 500, maxHeight = 245) {
  if (!image || !image.buffer) {
    doc
      .font('Helvetica-Oblique')
      .fontSize(9)
      .fillColor(COLORS.muted)
      .text(`${caption}: not available`, 48, doc.y + 2, {
        width: doc.page.width - 96,
      });
    doc.moveDown(0.8);
    return;
  }

  const sourceWidth = Number(image.width) || width;
  const sourceHeight = Number(image.height) || maxHeight;
  const scale = Math.min(width / sourceWidth, maxHeight / sourceHeight);
  const drawWidth = Math.max(1, sourceWidth * scale);
  const drawHeight = Math.max(1, sourceHeight * scale);
  const blockHeight = drawHeight + 26;

  if (doc.y + blockHeight > doc.page.height - 60) doc.addPage();
  doc
    .font('Helvetica-Bold')
    .fontSize(8.5)
    .fillColor(COLORS.muted)
    .text(
      `${caption} (${sourceWidth}×${sourceHeight}, aspect preserved)`,
      48,
      doc.y,
      { width: doc.page.width - 96 }
    );
  doc.moveDown(0.25);
  const x = 48 + Math.max(0, (width - drawWidth) / 2);
  try {
    doc.image(image.buffer, x, doc.y, {
      width: drawWidth,
      height: drawHeight,
    });
  } catch (error) {
    doc
      .font('Helvetica-Oblique')
      .fontSize(9)
      .fillColor(COLORS.danger)
      .text(
        `${caption}: image could not be embedded (${String(
          error.message || error
        ).slice(0, 160)}).`,
        48,
        doc.y,
        { width: doc.page.width - 96 }
      );
  }
  doc.y += drawHeight + 12;
}

function addWarnings(doc, warnings) {
  if (!warnings || !warnings.length) return;
  sectionTitle(doc, 'Warnings and limitations');
  doc.font('Helvetica').fontSize(8.5).fillColor(COLORS.charcoal);
  warnings.forEach((warning) => {
    doc.text(`• ${warning}`, 52, doc.y, { width: doc.page.width - 104 });
    doc.moveDown(0.35);
  });
  doc.moveDown(0.4);
}

const DEFECT_STATUS_LABELS = {
  detected: 'Detected',
  not_detected: 'Not detected',
  uncertain: 'Uncertain',
  error: 'Analysis unavailable',
};

function defectStatusColor(status) {
  if (status === 'detected') return COLORS.danger;
  if (status === 'uncertain') return COLORS.gold;
  if (status === 'error') return COLORS.danger;
  return COLORS.emerald;
}

function addDefects(doc, defects) {
  if (
    !defects ||
    typeof defects !== 'object' ||
    !defects.categories ||
    typeof defects.categories !== 'object' ||
    Array.isArray(defects.categories)
  ) {
    return;
  }
  const entries = Object.values(defects.categories).filter(
    (item) => item && item.status
  );
  if (!entries.length) return;

  sectionTitle(doc, 'Defect analysis (Gemini image-level review)');
  keyValue(doc, 'Analysis status', defects.analysisStatus || 'unknown', {
    width: 500,
    color:
      defects.analysisStatus === 'unavailable' || defects.analysisStatus === 'error'
        ? COLORS.danger
        : COLORS.charcoal,
  });
  keyValue(doc, 'Analysis method', 'Gemini vision, image-level', { width: 500 });
  keyValue(doc, 'Model', safe(defects.model), { width: 500 });
  keyValue(doc, 'Analyzed at', formatDate(defects.analyzedAt), { width: 500 });
  if (defects.error) {
    keyValue(doc, 'Reason', defects.error, { width: 500, color: COLORS.danger });
  }

  entries.forEach((item) => {
    keyValue(doc, item.name || item.key || 'Defect', DEFECT_STATUS_LABELS[item.status] || item.status, {
      width: 500,
      color: defectStatusColor(item.status),
    });
    doc
      .font('Helvetica')
      .fontSize(8.3)
      .fillColor(COLORS.charcoal)
      .text(safe(item.explanation), 153, doc.y, {
        width: doc.page.width - 201,
      });
    keyValue(
      doc,
      'Affected nuts',
      Number.isInteger(item.affectedNutCount)
        ? String(item.affectedNutCount)
        : 'Not established (requires a validated detector)',
      {
        width: 500,
        color: Number.isInteger(item.affectedNutCount)
          ? COLORS.charcoal
          : COLORS.muted,
      }
    );
    doc.moveDown(0.2);
  });

  if (Array.isArray(defects.limitations) && defects.limitations.length) {
    doc
      .font('Helvetica-Bold')
      .fontSize(8.5)
      .fillColor(COLORS.muted)
      .text('Limitations', 48, doc.y);
    doc.moveDown(0.2);
    doc.font('Helvetica').fontSize(8.3).fillColor(COLORS.charcoal);
    defects.limitations.forEach((item) => {
      doc.text(`• ${safe(item)}`, 52, doc.y, {
        width: doc.page.width - 104,
      });
      doc.moveDown(0.2);
    });
  }
  doc
    .font('Helvetica-Oblique')
    .fontSize(8)
    .fillColor(COLORS.danger)
    .text(
      safe(
        defects.note,
        'Image-level visual findings only. No defect location, bounding box, verified affected-nut count, or fungal confirmation is claimed.'
      ),
      48,
      doc.y,
      { width: doc.page.width - 96 }
    );
  doc.moveDown(0.7);
}

function defectSummaryLine(defects) {
  if (!defects || !defects.categories) return 'Not available';
  const entries = Object.values(defects.categories).filter((item) => item && item.status);
  if (!entries.length) return 'Not available';
  const detected = entries
    .filter((item) => item.status === 'detected')
    .map((item) => item.name);
  const uncertain = entries.filter((item) => item.status === 'uncertain').length;
  const unavailable = entries.filter((item) => item.status === 'error').length;
  const parts = [];
  if (detected.length) parts.push(`Detected: ${detected.join(', ')}`);
  if (uncertain) parts.push(`${uncertain} uncertain`);
  if (unavailable) parts.push(`${unavailable} unavailable`);
  return parts.length ? parts.join(' · ') : 'None detected';
}

function addMeasurements(doc, measurements) {
  sectionTitle(doc, 'Size and shape analysis (image space)');
  if (!measurements || !measurements.available) {
    doc
      .font('Helvetica')
      .fontSize(8.5)
      .fillColor(COLORS.charcoal)
      .text(
        'No bounding-box measurements are available. The model did not detect any arecanut regions.',
        48,
        doc.y,
        { width: doc.page.width - 96 }
      );
    doc.moveDown(0.7);
    return;
  }
  keyValue(doc, 'Method', measurements.method, { width: 500 });
  keyValue(doc, 'Units', measurements.units, { width: 500 });
  keyValue(doc, 'Average major axis', `${measurements.avg_major_axis_px} px`);
  keyValue(doc, 'Average minor axis', `${measurements.avg_minor_axis_px} px`);
  keyValue(doc, 'Average aspect ratio', measurements.avg_aspect_ratio);
  keyValue(doc, 'Average area', `${measurements.avg_area_px2} px²`);
  keyValue(doc, 'Physical dimensions', measurements.physical_dimensions, {
    width: 500,
  });
  keyValue(doc, 'Shape irregularity', measurements.shape_irregularity, {
    width: 500,
  });
  doc.moveDown(0.4);
}

function addGradeSupport(doc, scan) {
  const supported =
    Array.isArray(scan.supportedGrades) && scan.supportedGrades.length
      ? scan.supportedGrades
      : ['A', 'B'];
  sectionTitle(doc, 'Grade support');
  keyValue(doc, 'Model-supported grades', supported.join(', '), { width: 500 });
  const unsupported = ['A', 'B', 'C', 'D'].filter((letter) => !supported.includes(letter));
  if (unsupported.length) {
    keyValue(
      doc,
      'Not supported',
      `${unsupported.join(', ')} — the loaded checkpoint has no such class; no predictions are fabricated.`,
      { width: 500, color: COLORS.danger }
    );
  }
  doc.moveDown(0.4);
}

function addDetections(doc, detections) {
  if (!detections || !detections.length) return;
  sectionTitle(doc, `Detected regions (${detections.length})`);
  const rows = detections;
  const columns = [
    { key: 'id', label: 'Nut ID', width: 70 },
    { key: 'label', label: 'Class/Grade', width: 90 },
    { key: 'confidence_pct', label: 'Conf.', width: 70 },
    { key: 'bbox', label: 'Bounding box (x1, y1, x2, y2)', width: 230 },
    { key: 'size', label: 'Size (px)', width: 90 },
  ];
  let startY = doc.y;
  doc.font('Helvetica-Bold').fontSize(8).fillColor(COLORS.muted);
  let x = 48;
  columns.forEach((column) => {
    doc.text(column.label, x, startY, { width: column.width });
    x += column.width;
  });
  doc.y = startY + 14;

  doc.font('Helvetica').fontSize(7.5).fillColor(COLORS.charcoal);
  rows.forEach((detection, idx) => {
    if (doc.y > doc.page.height - 70) {
      doc.addPage();
      startY = doc.y;
      doc.font('Helvetica-Bold').fontSize(8).fillColor(COLORS.muted);
      x = 48;
      columns.forEach((column) => {
        doc.text(column.label, x, startY, { width: column.width });
        x += column.width;
      });
      doc.y = startY + 14;
      doc.font('Helvetica').fontSize(7.5).fillColor(COLORS.charcoal);
    }
    const y = doc.y;
    x = 48;
    const values = {
      id: detection.nut_id || detection.id || `Nut ${idx + 1}`,
      label: detection.label || detection.grade || 'Unknown',
      confidence_pct:
        detection.confidence_pct === undefined || detection.confidence_pct === null
          ? '—'
          : `${Number(detection.confidence_pct).toFixed(1)}%`,
      bbox: Array.isArray(detection.bbox)
        ? detection.bbox.map((value) => Math.round(value)).join(', ')
        : '—',
      size: detection.box_width_px && detection.box_height_px
        ? `${Math.round(detection.box_width_px)}×${Math.round(detection.box_height_px)}`
        : '—',
    };
    columns.forEach((column) => {
      doc.text(String(values[column.key]), x, y, { width: column.width, lineBreak: false });
      x += column.width;
    });
    doc.y = y + 12;
  });
  doc.moveDown(0.7);
}

function addGeminiAdvisory(doc, advisory) {
  if (!advisory || typeof advisory !== 'object') return;
  sectionTitle(doc, 'Gemini visual advisory (non-detector)');
  keyValue(doc, 'Status', advisory.status || 'unknown', {
    width: 500,
    color: advisory.status === 'ok' ? COLORS.charcoal : COLORS.danger,
  });
  keyValue(doc, 'Image-level hint', advisory.gradeHint || 'No hint', {
    width: 500,
  });
  keyValue(doc, 'Analysis method', 'Gemini vision, image-level', { width: 500 });
  keyValue(doc, 'Model', advisory.model || 'Not available', { width: 500 });
  if (advisory.analyzedAt) {
    keyValue(doc, 'Analyzed at', formatDate(advisory.analyzedAt), { width: 500 });
  }
  keyValue(doc, 'Advisory only', 'Yes — no Grade C/D counts or bounding boxes', {
    width: 500,
    color: COLORS.danger,
  });
  if (Array.isArray(advisory.evidence) && advisory.evidence.length) {
    doc
      .font('Helvetica-Bold')
      .fontSize(8.5)
      .fillColor(COLORS.muted)
      .text('Visual evidence', 48, doc.y);
    doc.moveDown(0.2);
    doc.font('Helvetica').fontSize(8.3).fillColor(COLORS.charcoal);
    advisory.evidence.forEach((item) => {
      doc.text(`• ${safe(item)}`, 52, doc.y, {
        width: doc.page.width - 104,
      });
      doc.moveDown(0.2);
    });
  }
  if (Array.isArray(advisory.limitations) && advisory.limitations.length) {
    doc
      .font('Helvetica-Bold')
      .fontSize(8.5)
      .fillColor(COLORS.muted)
      .text('Limitations', 48, doc.y);
    doc.moveDown(0.2);
    doc.font('Helvetica').fontSize(8.3).fillColor(COLORS.charcoal);
    advisory.limitations.forEach((item) => {
      doc.text(`• ${safe(item)}`, 52, doc.y, {
        width: doc.page.width - 104,
      });
      doc.moveDown(0.2);
    });
  }
  doc
    .font('Helvetica-Oblique')
    .fontSize(8)
    .fillColor(COLORS.danger)
    .text(
      safe(
        advisory.note,
        'This advisory is not a validated Grade C/D detector and must not be treated as a nut count or commercial grade.'
      ),
      48,
      doc.y,
      { width: doc.page.width - 96 }
    );
  doc.moveDown(0.6);
}

function addPricing(doc, pricing) {
  if (!pricing || !pricing.active) return;
  sectionTitle(doc, 'Price estimate');
  keyValue(doc, 'Pricing mode', pricing.mode === 'live' ? 'Live market price' : 'Manual price', {
    width: 500,
  });
  keyValue(doc, 'Status', pricing.status || 'unknown', {
    width: 500,
    color: pricing.status === 'ready' ? COLORS.charcoal : COLORS.gold,
  });
  keyValue(doc, 'Currency', pricing.currency || 'INR', { width: 500 });

  if (Array.isArray(pricing.lineItems) && pricing.lineItems.length) {
    doc.moveDown(0.25);
    doc.font('Helvetica-Bold').fontSize(8.5).fillColor(COLORS.muted);
    doc.text('Enabled grade prices', 48, doc.y);
    doc.moveDown(0.2);
    doc.font('Helvetica').fontSize(8.3).fillColor(COLORS.charcoal);
    pricing.lineItems.forEach((item) => {
      const subtotal =
        item.subtotal === null || item.subtotal === undefined
          ? 'subtotal needs measured weight'
          : `${pricing.currency} ${Number(item.subtotal).toFixed(2)}`;
      doc.text(
        `${item.label}: ${safe(item.count, 0)} nuts × ${safe(
          item.price
        )} ${item.unitLabel} — ${subtotal}`,
        52,
        doc.y,
        { width: doc.page.width - 104 }
      );
      doc.moveDown(0.2);
    });
  }

  if (pricing.totalValue !== null && pricing.totalValue !== undefined) {
    doc
      .font('Helvetica-Bold')
      .fontSize(10)
      .fillColor(COLORS.forest)
      .text(
        `Estimated total: ${pricing.currency} ${Number(pricing.totalValue).toFixed(2)}`,
        48,
        doc.y
      );
  } else {
    doc
      .font('Helvetica-Bold')
      .fontSize(9)
      .fillColor(COLORS.gold)
      .text(
        'Total value is not claimed: measured/calibrated net weight is required for this pricing unit.',
        48,
        doc.y,
        { width: doc.page.width - 96 }
      );
  }
  doc.moveDown(0.25);
  if (pricing.totalWeightKg) {
    keyValue(doc, 'Weight used', `${pricing.totalWeightKg} kg (${safe(pricing.weightSource)})`, {
      width: 500,
    });
  }
  if (pricing.livePrice && pricing.livePrice.source) {
    keyValue(doc, 'Market source', pricing.livePrice.source, { width: 500 });
    keyValue(
      doc,
      'Market quote',
      `${safe(pricing.livePrice.market)}, ${safe(pricing.livePrice.district)}, ${safe(
        pricing.livePrice.state
      )} — ${safe(pricing.livePrice.pricePerQuintal)} ${safe(
        pricing.livePrice.unit
      )} on ${safe(pricing.livePrice.arrivalDate)}`,
      { width: 500 }
    );
  }
  if (pricing.marketError) {
    keyValue(doc, 'Market error', pricing.marketError.message, {
      width: 500,
      color: COLORS.danger,
    });
  }
  doc
    .font('Helvetica')
    .fontSize(8)
    .fillColor(COLORS.charcoal)
    .text(safe(pricing.formula), 48, doc.y, { width: doc.page.width - 96 });
  doc.moveDown(0.25);
  doc
    .font('Helvetica-Oblique')
    .fontSize(7.8)
    .fillColor(COLORS.muted)
    .text(safe(pricing.note), 48, doc.y, { width: doc.page.width - 96 });
  doc.moveDown(0.6);
}

function addPolicySummary(doc, scan) {
  const policy = scan.predictionPolicy || {};
  sectionTitle(doc, 'Active display policy');
  keyValue(doc, 'Master prediction', policy.masterEnabled ? 'On' : 'Off', {
    width: 500,
  });
  keyValue(
    doc,
    'Enabled grades',
    Array.isArray(policy.enabledLetters) && policy.enabledLetters.length
      ? policy.enabledLetters.join(', ')
      : 'None',
    { width: 500 }
  );
  if (policy.defectDetectionEnabled) {
    keyValue(doc, 'Defect detection', 'On (Gemini image-level review)', {
      width: 500,
    });
    keyValue(
      doc,
      'Enabled defects',
      Array.isArray(policy.enabledDefectCategories)
        ? policy.enabledDefectCategories
            .map((key) => DEFECT_LABELS[key] || key)
            .join(', ')
        : 'None',
      { width: 500 }
    );
  }
  keyValue(doc, 'Pricing mode', policy.pricingMode || 'none', { width: 500 });
  keyValue(doc, 'Policy version', policy.version || '—', { width: 500 });
  doc.moveDown(0.4);
}

function addFooters(doc) {
  const range = doc.bufferedPageRange();
  for (let index = range.start; index < range.start + range.count; index += 1) {
    doc.switchToPage(index);
    const pageNumber = index + 1;
    // The footer sits inside the bottom margin. Without this, PDFKit treats the
    // draw as overflowing and appends an extra blank page per footer.
    const previousBottom = doc.page.margins.bottom;
    doc.page.margins.bottom = 0;
    doc
      .font('Helvetica')
      .fontSize(7.5)
      .fillColor(COLORS.muted)
      .text(
        'Automated estimate — not a certified commercial grade · ARECANUT QUALITY GRADING SYSTEM',
        48,
        doc.page.height - 42,
        { width: doc.page.width - 96, align: 'left', lineBreak: false }
      );
    doc.text(`Page ${pageNumber} of ${range.count}`, 48, doc.page.height - 42, {
      width: doc.page.width - 96,
      align: 'right',
      lineBreak: false,
    });
    doc.page.margins.bottom = previousBottom;
  }
}

function collectPdf(doc) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    doc.on('data', (chunk) => chunks.push(chunk));
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);
    doc.end();
  });
}

async function buildPredictionReport(scan, images = {}, options = {}) {
  const doc = new PDFDocument({
    size: 'A4',
    margins: { top: 48, bottom: 60, left: 48, right: 48 },
    bufferPages: true,
    info: {
      Title: `Arecanut Grading Report ${scan.reportId || scan._id}`,
      Author: 'ARECANUT QUALITY GRADING SYSTEM',
      Subject: 'Automated arecanut quality grading report',
    },
  });

  const prepared = await prepareImages(images);
  const gradingEnabled = scan.gradingEnabled !== false;

  drawHeader(doc, `Report ${scan.reportId || scan._id}`);

  doc
    .font('Helvetica-Bold')
    .fontSize(18)
    .fillColor(COLORS.charcoal)
    .text('Quality grading report', 48, doc.y);
  doc.moveDown(0.2);
  doc
    .font('Helvetica')
    .fontSize(8.5)
    .fillColor(COLORS.muted)
    .text(
      `Generated ${formatDate(new Date())} · Prediction ${formatDate(
        scan.createdAt
      )}`,
      48,
      doc.y
    );
  doc.moveDown(0.9);

  // Result card. When the master switch is off this card must not contain a
  // grade, count, confidence, quality score, or price.
  const cardY = doc.y;
  doc.roundedRect(48, cardY, doc.page.width - 96, 92, 10).fill(COLORS.mint);
  doc
    .font('Helvetica')
    .fontSize(8)
    .fillColor(COLORS.muted)
    .text(gradingEnabled ? 'FINAL GRADE' : 'GRADING STATUS', 66, cardY + 14);
  doc
    .font('Helvetica-Bold')
    .fontSize(gradingEnabled ? 26 : 14)
    .fillColor(gradingEnabled ? gradeColor(scan.finalGrade) : COLORS.danger)
    .text(
      gradingEnabled ? gradeLabel(scan, scan.finalGrade) : 'Disabled by administrator',
      66,
      cardY + 30,
      { width: 220 }
    );
  if (gradingEnabled) {
    doc
      .font('Helvetica')
      .fontSize(9)
      .fillColor(COLORS.charcoal)
      .text(
        `Confidence: ${
          scan.confidence === null || scan.confidence === undefined
            ? 'Not available'
            : `${Number(scan.confidence).toFixed(1)}%`
        }`,
        300,
        cardY + 30
      )
      .text(
        `Quality score: ${
          scan.qualityScore === null || scan.qualityScore === undefined
            ? 'Not available'
            : `${Number(scan.qualityScore).toFixed(1)} / 100 (heuristic)`
        }`,
        300,
        cardY + 46
      )
      .text(`Detected nuts: ${gradeCountsText(scan)}`, 300, cardY + 62);
  } else {
    doc
      .font('Helvetica')
      .fontSize(9)
      .fillColor(COLORS.charcoal)
      .text(
        'Grade, count, confidence, quality, chart and price sections are hidden by the active display policy.',
        300,
        cardY + 34,
        { width: doc.page.width - 366 }
      );
  }
  doc.y = cardY + 112;

  sectionTitle(doc, 'Prediction details');
  keyValue(doc, 'Report ID', scan.reportId || scan._id);
  keyValue(doc, 'Prediction time', formatDate(scan.createdAt));
  keyValue(doc, 'Processing duration', `${safe(scan.processingMs, '—')} ms`);
  keyValue(doc, 'Model', `${safe(scan.modelId)} v${safe(scan.modelVersion)}`);
  keyValue(doc, 'Model SHA-256', safe(scan.modelChecksum), { width: 500 });
  keyValue(doc, 'Original filename', safe(scan.filename), { width: 500 });
  if (gradingEnabled && scan.confidenceMethod) {
    keyValue(doc, 'Confidence method', scan.confidenceMethod, { width: 500 });
  }
  if (gradingEnabled && scan.qualityMethod) {
    keyValue(doc, 'Quality method', scan.qualityMethod, { width: 500 });
  }
  doc.moveDown(0.5);

  if (gradingEnabled) addGradeSupport(doc, scan);

  sectionTitle(doc, 'Evidence images');
  addImage(doc, prepared.original, 'Original image');
  if (gradingEnabled) {
    addImage(doc, prepared.processed, 'Processed image (model-input preview)', 500, 235);
    if (scan.annotatedImageAllowed === false) {
      doc
        .font('Helvetica-Oblique')
        .fontSize(8.5)
        .fillColor(COLORS.muted)
        .text(
          'The annotated image is hidden because it contains boxes for a grade disabled by the active display policy.',
          48,
          doc.y,
          { width: doc.page.width - 96 }
        );
      doc.moveDown(0.5);
    } else {
      addImage(doc, prepared.annotated, 'Annotated image (model detections)', 500, 235);
    }
  } else {
    doc
      .font('Helvetica-Oblique')
      .fontSize(8.5)
      .fillColor(COLORS.muted)
      .text(
        'Processed and annotated model-output images are hidden while master prediction is off.',
        48,
        doc.y,
        { width: doc.page.width - 96 }
      );
    doc.moveDown(0.5);
  }
  if (prepared.errors.length) {
    doc
      .font('Helvetica-Oblique')
      .fontSize(8.5)
      .fillColor(COLORS.danger)
      .text(
        `Image normalization warning: ${prepared.errors
          .map((item) => `${item.kind} (${item.message})`)
          .join('; ')}`,
        48,
        doc.y,
        { width: doc.page.width - 96 }
      );
    doc.moveDown(0.5);
  }

  addDefects(doc, scan.defects);

  if (gradingEnabled) {
    addMeasurements(doc, scan.measurements);
    addDetections(doc, scan.detections);
    addGeminiAdvisory(doc, scan.geminiAdvisory);
    addPricing(doc, scan.pricing);
    addWarnings(doc, scan.warnings);

    sectionTitle(doc, 'Result summary');
    doc
      .font('Helvetica')
      .fontSize(9)
      .fillColor(COLORS.charcoal)
      .text(
        scan.totalCount > 0 && scan.finalGrade
          ? `The model detected ${scan.totalCount} enabled arecanut region(s) and assigned the image-level grade ${scan.finalGrade}. Grade composition: ${gradeCountsText(
              scan
            ).replace(/^\d+\s*/, '')}.`
          : scan.unavailableGrades && scan.unavailableGrades.length
          ? `The enabled Grade ${scan.unavailableGrades.join(
              '/'
            )} review is advisory only. No validated Grade C/D detector exists, so no Grade C/D nut count or final commercial grade is claimed.`
          : 'No arecanut regions were detected above the configured confidence threshold. The image-level result is Invalid. Please retake the photo with better lighting and less overlap.',
        48,
        doc.y,
        { width: doc.page.width - 96, align: 'justify' }
      );
    doc.moveDown(0.7);
  }

  addPolicySummary(doc, scan);

  doc
    .font('Helvetica-Oblique')
    .fontSize(7.5)
    .fillColor(COLORS.muted)
    .text(DISCLAIMER, 48, doc.y, { width: doc.page.width - 96 });

  addFooters(doc);
  return collectPdf(doc);
}

async function buildComparisonReport(scans, imageSets = [], options = {}) {
  const doc = new PDFDocument({
    size: 'A4',
    margins: { top: 48, bottom: 60, left: 48, right: 48 },
    bufferPages: true,
    info: {
      Title: 'Arecanut comparison report',
      Author: 'ARECANUT QUALITY GRADING SYSTEM',
    },
  });

  const preparedSets = await Promise.all(imageSets.map((set) => prepareImages(set)));
  const gradingEnabled = scans.some((scan) => scan.gradingEnabled !== false);

  drawHeader(doc, 'Prediction comparison');
  doc
    .font('Helvetica-Bold')
    .fontSize(18)
    .fillColor(COLORS.charcoal)
    .text('Comparison report', 48, doc.y);
  doc
    .font('Helvetica')
    .fontSize(8.5)
    .fillColor(COLORS.muted)
    .text(
      `Generated ${formatDate(new Date())} · ${scans.length} predictions compared`,
      48,
      doc.y + 2
    );
  doc.moveDown(1);

  sectionTitle(doc, 'Side-by-side summary');
  const labels = [
    ['Report ID', (scan) => scan.reportId || scan._id],
    ['Prediction time', (scan) => formatDate(scan.createdAt)],
    ...(gradingEnabled
      ? [
          ['Grade', (scan) => gradeLabel(scan, scan.finalGrade)],
          [
            'Confidence',
            (scan) =>
              scan.gradingEnabled === false ||
              scan.confidence === null ||
              scan.confidence === undefined
                ? '—'
                : `${Number(scan.confidence).toFixed(1)}%`,
          ],
          [
            'Quality score',
            (scan) =>
              scan.gradingEnabled === false ||
              scan.qualityScore === null ||
              scan.qualityScore === undefined
                ? '—'
                : `${Number(scan.qualityScore).toFixed(1)} / 100 (heuristic)`,
          ],
          ['Detected nuts', (scan) => gradeCountsText(scan)],
          ...(scans.some((scan) => scan.defects)
            ? [['Defect findings', (scan) => defectSummaryLine(scan.defects)]]
            : []),
          [
            'Avg aspect ratio',
            (scan) =>
              scan.gradingEnabled === false
                ? '—'
                : scan.measurements && scan.measurements.avg_aspect_ratio
                ? scan.measurements.avg_aspect_ratio
                : '—',
          ],
          [
            'Price estimate',
            (scan) =>
              scan.pricing && scan.pricing.active
                ? scan.pricing.totalValue !== null && scan.pricing.totalValue !== undefined
                  ? `${scan.pricing.currency} ${Number(scan.pricing.totalValue).toFixed(2)}`
                  : 'Weight required'
                : 'Not active',
          ],
        ]
      : []),
    ['Model', (scan) => `${safe(scan.modelId)} v${safe(scan.modelVersion)}`],
  ];

  labels.forEach(([label, getter], index) => {
    const y = doc.y;
    doc
      .font('Helvetica')
      .fontSize(8.5)
      .fillColor(COLORS.muted)
      .text(label, 48, y, { width: 110 });
    doc
      .font('Helvetica-Bold')
      .fontSize(8.5)
      .fillColor(COLORS.charcoal);
    scans.forEach((scan, scanIndex) => {
      doc.text(getter(scan), 165 + scanIndex * 190, y, { width: 180 });
    });
    doc.y = y + 16;
    if (index === labels.length - 1) doc.moveDown(0.5);
  });

  sectionTitle(doc, 'Evidence images');
  for (let index = 0; index < scans.length; index += 1) {
    const scan = scans[index];
    doc
      .font('Helvetica-Bold')
      .fontSize(10)
      .fillColor(COLORS.forest)
      .text(
        gradingEnabled
          ? `${index + 1}. ${scan.reportId || scan._id} — ${gradeLabel(
              scan,
              scan.finalGrade
            )}`
          : `${index + 1}. ${scan.reportId || scan._id}`,
        48,
        doc.y
      );
    doc.moveDown(0.3);
    const prepared = preparedSets[index] || {};
    addImage(doc, prepared.original, 'Original image');
    if (gradingEnabled) {
      addImage(
        doc,
        prepared.processed,
        'Processed image (model-input preview)',
        500,
        235
      );
      if (scan.annotatedImageAllowed === false) {
        doc
          .font('Helvetica-Oblique')
          .fontSize(8.5)
          .fillColor(COLORS.muted)
          .text(
            'Annotated image hidden because it contains a grade disabled by policy.',
            48,
            doc.y,
            { width: doc.page.width - 96 }
          );
        doc.moveDown(0.5);
      } else {
        addImage(
          doc,
          prepared.annotated,
          'Annotated image (model detections)',
          500,
          235
        );
      }
    }
    addDefects(doc, scan.defects);
    if (gradingEnabled && scan.geminiAdvisory) {
      addGeminiAdvisory(doc, scan.geminiAdvisory);
    }
    if (gradingEnabled) addWarnings(doc, scan.warnings);
  }

  if (scans[0]) addPolicySummary(doc, scans[0]);

  doc
    .font('Helvetica-Oblique')
    .fontSize(7.5)
    .fillColor(COLORS.muted)
    .text(
      'Comparison does not imply that the same physical nut was tracked across images.',
      48,
      doc.y,
      { width: doc.page.width - 96 }
    );
  doc.moveDown(0.4);
  doc.text(DISCLAIMER, 48, doc.y, { width: doc.page.width - 96 });

  addFooters(doc);
  return collectPdf(doc);
}

module.exports = { buildPredictionReport, buildComparisonReport };
